// Embeds the Drizzle migrations in a TypeScript module so the database layer never reads them
// from disk at runtime. That keeps `bun build --compile` binaries and trimmed Docker images working.
// Run by `db:generate` and `build`; a test fails if the generated file is stale.
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const folder = fileURLToPath(new URL('../migrations/', import.meta.url));
const target = fileURLToPath(new URL('../src/migrations.generated.ts', import.meta.url));
const journal = JSON.parse(readFileSync(`${folder}meta/_journal.json`, 'utf8'));
const migrations = journal.entries.map((entry) => ({
  tag: entry.tag,
  when: entry.when,
  breakpoints: entry.breakpoints,
  sql: readFileSync(`${folder}${entry.tag}.sql`, 'utf8'),
}));
writeFileSync(
  target,
  `// Generated by scripts/embed-migrations.mjs from ../migrations. Do not edit.\nexport const embeddedMigrations: readonly { tag: string; when: number; breakpoints: boolean; sql: string }[] = ${JSON.stringify(migrations, null, 2)};\n`,
);
